#include <vector>

class Solution {
    struct DSU {
        std::vector<int> parent, pot;
        DSU(int n) : parent(n), pot(n, 0) {
            for (int i = 0; i < n; ++i) parent[i] = i;
        }
        std::pair<int, int> find(int x) {
            if (parent[x] != x) {
                auto [p, par_pot] = find(parent[x]);
                parent[x] = p;
                pot[x] ^= par_pot;
            }
            return {parent[x], pot[x]};
        }
        bool unite(int u, int v, int w) {
            auto [root_u, pot_u] = find(u);
            auto [root_v, pot_v] = find(v);
            int parity = w % 2;
            if (root_u == root_v) {
                return (pot_u ^ pot_v ^ parity) == 0;
            } else {
                parent[root_u] = root_v;
                pot[root_u] = pot_u ^ pot_v ^ parity;
                return false;
            }
        }
    };
public:
    std::vector<bool> evenWeightedCycleQueries(int n, std::vector<std::vector<int>>& edges) {
        DSU dsu(n);
        std::vector<bool> ans;
        bool found = false;
        for (const auto& e : edges) {
            if (dsu.unite(e[0], e[1], e[2])) found = true;
            ans.push_back(found);
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    static class DSU {
        int[] parent, pot;
        DSU(int n) {
            parent = new int[n];
            pot = new int[n];
            for (int i = 0; i < n; i++) parent[i] = i;
        }
        int[] find(int x) {
            if (parent[x] != x) {
                int[] res = find(parent[x]);
                parent[x] = res[0];
                pot[x] ^= res[1];
            }
            return new int[]{parent[x], pot[x]};
        }
        boolean union(int u, int v, int w) {
            int[] resU = find(u);
            int[] resV = find(v);
            int parity = w % 2;
            if (resU[0] == resV[0]) {
                return (resU[1] ^ resV[1] ^ parity) == 0;
            } else {
                parent[resU[0]] = resV[0];
                pot[resU[0]] = resU[1] ^ resV[1] ^ parity;
                return false;
            }
        }
    }

    public boolean[] evenWeightedCycleQueries(int n, int[][] edges) {
        DSU dsu = new DSU(n);
        boolean[] ans = new boolean[edges.length];
        boolean found = false;
        for (int i = 0; i < edges.length; i++) {
            if (dsu.union(edges[i][0], edges[i][1], edges[i][2])) found = true;
            ans[i] = found;
        }
        return ans;
    }
}

function evenWeightedCycleQueries(n, edges) {
    const parent = Array.from({length: n}, (_, i) => i);
    const pot = new Array(n).fill(0);
    const find = (x) => {
        if (parent[x] !== x) {
            const [p, parPot] = find(parent[x]);
            parent[x] = p;
            pot[x] ^= parPot;
        }
        return [parent[x], pot[x]];
    };
    const union = (u, v, w) => {
        const [ru, pu] = find(u);
        const [rv, pv] = find(v);
        const parity = w % 2;
        if (ru === rv) {
            return (pu ^ pv ^ parity) === 0;
        } else {
            parent[ru] = rv;
            pot[ru] = pu ^ pv ^ parity;
            return false;
        }
    };
    const ans = [];
    let found = false;
    for (const [u, v, w] of edges) {
        if (union(u, v, w)) found = true;
        ans.push(found);
    }
    return ans;
}
